            if (c == ' ') continue;
            if (Character.isLetter(c)) c = Character.toLowerCase(c);
            count[c]++;
        }

        for (char c : s2.toCharArray()) {
            if (c == ' ') continue;
            if (Character.isLetter(c)) c = Character.toLowerCase(c);
